import { cn } from "@/lib/utils"

import { formatClock } from "./playback"
import type { ReplayMarker } from "./types"

const SHAPES: Record<string, string> = {
  click: "size-2 rounded-full bg-primary",
  navigation: "size-2 rotate-45 rounded-[1px] bg-muted-foreground",
  error: "h-3 w-1.5 rounded-[1px] bg-destructive",
}

/** One mark per event over the seek slider, with a playhead line. Marks are pointer-only: the skip button and the list times reach the same moments from the keyboard. */
export function MarkerLane({
  markers,
  durationMs,
  time,
  onSeek,
  className,
}: {
  markers: ReplayMarker[]
  durationMs: number
  time: number
  onSeek: (ms: number) => void
  className?: string
}) {
  const playhead = durationMs > 0 ? Math.min(1, time / durationMs) * 100 : 0
  return (
    <div aria-hidden className={cn("relative h-4 w-full", className)}>
      <div
        className="absolute inset-y-0 w-px -translate-x-1/2 bg-primary"
        style={{ left: `${playhead}%` }}
      />
      {markers.map((marker) => (
        <button
          key={marker.id}
          type="button"
          tabIndex={-1}
          title={`${marker.kind} at ${formatClock(marker.at)}`}
          onClick={() => onSeek(marker.at)}
          className="absolute top-1/2 flex size-4 -translate-x-1/2 -translate-y-1/2 cursor-pointer items-center justify-center"
          style={{ left: `${marker.percent}%` }}
        >
          <span className={cn("block", SHAPES[marker.kind] ?? SHAPES.click)} />
        </button>
      ))}
    </div>
  )
}

import type { ReplayEvent, ReplayMarker, ReplaySnapshot } from "./types"

export const MARKER_KINDS = ["click", "navigation", "error"]
export const SPEEDS = [0.5, 1, 2, 4]
export const RIPPLE_MS = 700

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value))
}

/** Stable sort by `at`, so callers may pass events and snapshots in any order. */
export function sortByTime<T extends { at: number }>(items: T[]): T[] {
  return items
    .map((item, index) => ({ item, index }))
    .sort((a, b) => a.item.at - b.item.at || a.index - b.index)
    .map(({ item }) => item)
}

/** Time after playing `elapsedMs` of wall clock at `speed`; stops at the end. */
export function advance(
  time: number,
  elapsedMs: number,
  speed: number,
  durationMs: number
): { time: number; ended: boolean } {
  const next = time + elapsedMs * speed
  if (next >= durationMs) return { time: durationMs, ended: true }
  return { time: Math.max(0, next), ended: false }
}

export function seekBy(time: number, deltaMs: number, durationMs: number): number {
  return clamp(time + deltaMs, 0, durationMs)
}

/** The last snapshot at or before `time`, or the first one when the playhead is before all of them. Expects snapshots sorted by `at`. */
export function snapshotAt<S>(
  snapshots: ReplaySnapshot<S>[],
  time: number
): ReplaySnapshot<S> | undefined {
  let found: ReplaySnapshot<S> | undefined
  for (const snapshot of snapshots) {
    if (snapshot.at <= time) found = snapshot
    else break
  }
  return found ?? snapshots[0]
}

/** Time of the first click, navigation or error strictly after `time`, or the end when none is left. */
export function nextEventTime(
  events: ReplayEvent[],
  time: number,
  durationMs: number
): number {
  let best = durationMs
  for (const event of events) {
    if (!MARKER_KINDS.includes(event.kind)) continue
    if (event.at > time && event.at < best) best = event.at
  }
  return best
}

export function markerPositions(
  events: ReplayEvent[],
  durationMs: number
): ReplayMarker[] {
  if (durationMs <= 0) return []
  return sortByTime(events.filter((event) => MARKER_KINDS.includes(event.kind))).map(
    (event) => ({
      id: event.id,
      kind: event.kind,
      at: event.at,
      percent: clamp(event.at / durationMs, 0, 1) * 100,
    })
  )
}

/** Index of the last entry at or before `time`, or -1. Expects entries sorted by `at`. */
export function activeIndex(entries: ReplayEvent[], time: number): number {
  let found = -1
  for (let i = 0; i < entries.length; i++) {
    if (entries[i].at <= time) found = i
    else break
  }
  return found
}

/** Where the cursor sits: the latest click with a point at or before `time`. */
export function cursorAt(
  events: ReplayEvent[],
  time: number
): { x: number; y: number; ageMs: number } | undefined {
  let latest: ReplayEvent | undefined
  for (const event of events) {
    if (event.kind !== "click" || !event.point || event.at > time) continue
    if (!latest || event.at >= latest.at) latest = event
  }
  if (!latest?.point) return undefined
  return { x: latest.point.x, y: latest.point.y, ageMs: time - latest.at }
}

export function countByKind(events: ReplayEvent[], kind: string): number {
  return events.filter((event) => event.kind === kind).length
}

export function stepSpeed(speed: number, direction: 1 | -1): number {
  const index = SPEEDS.indexOf(speed)
  const from = index === -1 ? SPEEDS.indexOf(1) : index
  return SPEEDS[clamp(from + direction, 0, SPEEDS.length - 1)]
}

export function formatSpeed(speed: number): string {
  return `${speed}×`
}

export function formatClock(ms: number, withMillis = false): string {
  const safe = Math.max(0, ms)
  const totalSeconds = Math.floor(safe / 1000)
  const minutes = String(Math.floor(totalSeconds / 60)).padStart(2, "0")
  const seconds = String(totalSeconds % 60).padStart(2, "0")
  if (!withMillis) return `${minutes}:${seconds}`
  return `${minutes}:${seconds}.${String(Math.floor(safe % 1000)).padStart(3, "0")}`
}

export function filterEntries(entries: ReplayEvent[], query: string): ReplayEvent[] {
  const needle = query.trim().toLowerCase()
  if (!needle) return entries
  return entries.filter((entry) =>
    `${entry.label} ${entry.detail ?? ""}`.toLowerCase().includes(needle)
  )
}

export function isPlayable(recording: {
  durationMs: number
  snapshots: unknown[]
}): boolean {
  return recording.durationMs > 0 && recording.snapshots.length > 0
}

import { useMemo, useRef, type ReactNode } from "react"
import { useHotkeys } from "react-hotkeys-hook"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { cn } from "@/lib/utils"

import { ControlBar } from "./control-bar"
import {
  countByKind,
  cursorAt,
  formatClock,
  isPlayable,
  markerPositions,
  nextEventTime,
  snapshotAt,
  sortByTime,
} from "./playback"
import { TimedList } from "./timed-list"
import type { ReplayRecording, ReplaySnapshot, ReplayTab } from "./types"
import { usePlayback } from "./use-playback"
import { UrlBar, Viewport } from "./viewport"

export type ReplayPlayerProps<S> = {
  items: ReplayRecording<S>[]
  status?: "loading" | "ready" | "error"
  error?: Error
  onRetry?: () => void
  renderSnapshot: (snapshot: ReplaySnapshot<S>) => ReactNode
  activeId?: string
  extraTabs?: ReplayTab[]
  emptyTitle?: string
  "aria-label"?: string
}

const BUILT_IN_TABS: ReplayTab[] = [
  {
    id: "activity",
    label: "Activity",
    kinds: ["click", "navigation", "error"],
    emptyTitle: "No activity in this replay",
  },
  {
    id: "console",
    label: "Console",
    kinds: ["console"],
    emptyTitle: "No console messages",
  },
  {
    id: "network",
    label: "Network",
    kinds: ["network"],
    emptyTitle: "No requests in this replay",
  },
  {
    id: "errors",
    label: "Errors",
    kinds: ["error"],
    emptyTitle: "No errors in this replay",
    emptyDescription: "Nothing failed while this was recorded.",
  },
]

/**
 * Plays back a recording of snapshots with transport controls, a marker lane,
 * and tabs of timed lists that follow the playhead and seek on click.
 * Takes `items` and `status` as props and never reads the store.
 */
export function ReplayPlayer<S>({
  items,
  status = "ready",
  error,
  onRetry,
  renderSnapshot,
  activeId,
  extraTabs = [],
  emptyTitle = "No replay to show",
  "aria-label": ariaLabel = "Replay player",
}: ReplayPlayerProps<S>) {
  const recording = items.find((item) => item.id === activeId) ?? items[0]
  let body: ReactNode
  if (status === "loading") {
    body = <LoadingState label="Loading replay" />
  } else if (status === "error") {
    body = (
      <ErrorState
        error={error ?? new Error("The replay could not be loaded.")}
        onRetry={onRetry}
      />
    )
  } else if (!recording || !isPlayable(recording)) {
    body = <EmptyState title={emptyTitle} />
  } else {
    body = (
      <Player
        key={recording.id}
        recording={recording}
        renderSnapshot={renderSnapshot}
        tabs={[...BUILT_IN_TABS, ...extraTabs]}
        ariaLabel={ariaLabel}
      />
    )
  }
  return (
    <div className="@container flex h-full min-h-[34rem] flex-col">
      {body}
    </div>
  )
}

function Player<S>({
  recording,
  renderSnapshot,
  tabs,
  ariaLabel,
}: {
  recording: ReplayRecording<S>
  renderSnapshot: (snapshot: ReplaySnapshot<S>) => ReactNode
  tabs: ReplayTab[]
  ariaLabel: string
}) {
  const { durationMs } = recording
  const rootRef = useRef<HTMLDivElement>(null)
  const playback = usePlayback(durationMs)
  const { time } = playback

  const events = useMemo(
    () =>
      sortByTime(recording.events).map((event) => ({
        ...event,
        at: Math.min(Math.max(event.at, 0), durationMs),
      })),
    [recording.events, durationMs]
  )
  const snapshots = useMemo(() => sortByTime(recording.snapshots), [recording.snapshots])
  const markers = useMemo(() => markerPositions(events, durationMs), [events, durationMs])
  const byTab = useMemo(
    () =>
      tabs.map((tab) => ({
        tab,
        entries: events.filter((event) => tab.kinds.includes(event.kind)),
      })),
    [tabs, events]
  )

  const snapshot = snapshotAt(snapshots, time)
  const cursor = cursorAt(events, time)
  const clicks = countByKind(events, "click")
  const errors = countByKind(events, "error")

  const inScope = (event: KeyboardEvent) => {
    const target = event.target
    if (target === document.body || target === document.documentElement) return true
    return target instanceof Node && rootRef.current?.contains(target) === true
  }
  const onTab = (event: KeyboardEvent) =>
    event.target instanceof Element && event.target.closest('[role="tab"]') !== null
  // Space on these activates them natively; the slider handles its own arrows
  const nativeSpace = (event: KeyboardEvent) =>
    event.target instanceof Element &&
    event.target.closest('button, a, [role="tab"]') !== null
  const onSlider = (event: KeyboardEvent) =>
    event.target instanceof Element && event.target.closest('[role="slider"]') !== null

  useHotkeys("space", (event) => {
    if (!inScope(event) || nativeSpace(event)) return
    event.preventDefault()
    if (event.repeat) return
    playback.toggle()
  })
  useHotkeys("left", (event) => {
    if (!inScope(event) || onTab(event) || onSlider(event)) return
    event.preventDefault()
    playback.skip(-5000)
  })
  useHotkeys("right", (event) => {
    if (!inScope(event) || onTab(event) || onSlider(event)) return
    event.preventDefault()
    playback.skip(5000)
  })

  return (
    <div
      ref={rootRef}
      role="region"
      aria-label={ariaLabel}
      className="flex min-h-0 flex-1 flex-col"
    >
      <span role="status" className="sr-only">
        {playback.playing ? "Playing" : "Paused"}
      </span>
      <header className="flex shrink-0 items-center gap-3 border-b px-3 py-2">
        <span
          aria-hidden
          className="flex size-8 shrink-0 items-center justify-center rounded-full bg-muted text-sm font-medium uppercase"
        >
          {recording.user.slice(0, 1)}
        </span>
        <div className="min-w-0 flex-1">
          <p className="truncate text-sm font-medium">{recording.user}</p>
          <p className="truncate text-xs text-muted-foreground">
            {[recording.meta, recording.whenLabel, formatClock(durationMs)]
              .filter(Boolean)
              .join(" · ")}
          </p>
        </div>
        <dl className="flex shrink-0 gap-4 text-right">
          <div>
            <dt className="text-xs text-muted-foreground">Clicks</dt>
            <dd className="text-sm font-medium tabular-nums">{clicks}</dd>
          </div>
          <div>
            <dt className="text-xs text-muted-foreground">Errors</dt>
            <dd
              className={cn(
                "text-sm font-medium tabular-nums",
                errors > 0 && "text-destructive"
              )}
            >
              {errors}
            </dd>
          </div>
        </dl>
      </header>
      <div className="flex min-h-0 flex-1 flex-col overflow-y-auto @3xl:flex-row @3xl:overflow-hidden">
        <section
          tabIndex={0}
          aria-label="Player"
          className="flex min-h-[30rem] min-w-0 shrink-0 flex-col gap-2 p-3 @3xl:min-h-0 outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset @3xl:basis-[42%]"
        >
          <UrlBar url={snapshot?.url ?? ""} />
          <Viewport time={formatClock(time)} url={snapshot?.url ?? ""} cursor={cursor}>
            {snapshot ? renderSnapshot(snapshot) : null}
          </Viewport>
          <ControlBar
            time={time}
            durationMs={durationMs}
            playing={playback.playing}
            ended={playback.ended}
            speed={playback.speed}
            markers={markers}
            onToggle={playback.toggle}
            onBack={() => playback.skip(-10_000)}
            onSkip={() => playback.seek(nextEventTime(events, time, durationMs))}
            onSeek={playback.seek}
            onStepSpeed={playback.changeSpeed}
          />
        </section>
        <Tabs
          defaultValue={tabs[0]?.id}
          className="min-h-[18rem] min-w-0 flex-1 gap-0 border-t pt-2 @3xl:border-t-0 @3xl:border-l"
        >
          <TabsList
            variant="line"
            className="h-auto w-full shrink-0 flex-wrap justify-start px-2"
          >
            {tabs.map((tab) => (
              <TabsTrigger key={tab.id} value={tab.id} className="flex-none px-2">
                {tab.label}
              </TabsTrigger>
            ))}
          </TabsList>
          {byTab.map(({ tab, entries }) => (
            <TabsContent
              key={tab.id}
              value={tab.id}
              className="mt-2 flex min-h-0 flex-1 flex-col"
            >
              <TimedList
                entries={entries}
                time={time}
                onSeek={playback.seek}
                label={tab.label}
                emptyTitle={tab.emptyTitle}
                emptyDescription={tab.emptyDescription}
              />
            </TabsContent>
          ))}
        </Tabs>
      </div>
    </div>
  )
}

import { useRef, useState, type KeyboardEvent, type PointerEvent } from "react"

import { cn } from "@/lib/utils"

import { clamp, formatClock } from "./playback"

const STEP_MS = 5000
const PAGE_MS = 30000

/** Time slider with a filled track, a floating time with milliseconds under the pointer, and the standard slider keys. */
export function SeekSlider({
  value,
  max,
  onChange,
  onSpace,
  label = "Seek",
  className,
}: {
  value: number
  max: number
  onChange: (ms: number) => void
  /** Called on Space; the keyboard layer ignores keys on a slider, so the slider forwards this one. */
  onSpace?: () => void
  label?: string
  className?: string
}) {
  const trackRef = useRef<HTMLDivElement>(null)
  const dragging = useRef(false)
  const [hover, setHover] = useState<number | null>(null)

  const timeAt = (clientX: number) => {
    const rect = trackRef.current?.getBoundingClientRect()
    if (!rect || rect.width === 0) return 0
    return clamp((clientX - rect.left) / rect.width, 0, 1) * max
  }

  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return
    dragging.current = true
    event.currentTarget.setPointerCapture(event.pointerId)
    event.currentTarget.focus({ preventScroll: true })
    const at = timeAt(event.clientX)
    setHover(at)
    onChange(at)
  }

  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const at = timeAt(event.clientX)
    setHover(at)
    if (dragging.current) onChange(at)
  }

  const onPointerUp = (event: PointerEvent<HTMLDivElement>) => {
    dragging.current = false
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }
  }

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === " " && onSpace) {
      event.preventDefault()
      event.stopPropagation()
      if (!event.repeat) onSpace()
      return
    }
    let next: number | null = null
    if (event.key === "ArrowRight" || event.key === "ArrowUp") next = value + STEP_MS
    else if (event.key === "ArrowLeft" || event.key === "ArrowDown") next = value - STEP_MS
    else if (event.key === "PageUp") next = value + PAGE_MS
    else if (event.key === "PageDown") next = value - PAGE_MS
    else if (event.key === "Home") next = 0
    else if (event.key === "End") next = max
    if (next === null) return
    event.preventDefault()
    event.stopPropagation()
    onChange(clamp(next, 0, max))
  }

  const percent = max > 0 ? clamp(value / max, 0, 1) * 100 : 0
  const floating = hover

  return (
    <div
      role="slider"
      tabIndex={0}
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={Math.round(value)}
      aria-valuetext={`${formatClock(value)} of ${formatClock(max)}`}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      onPointerLeave={() => {
        if (!dragging.current) setHover(null)
      }}
      onKeyDown={onKeyDown}
      className={cn(
        "group relative flex h-5 cursor-pointer touch-none items-center rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-ring",
        className
      )}
    >
      <div ref={trackRef} className="relative h-1.5 w-full rounded-full bg-muted">
        <div
          className="absolute inset-y-0 left-0 rounded-full bg-primary"
          style={{ width: `${percent}%` }}
        />
        <div
          className="absolute top-1/2 size-3.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-background bg-primary shadow-sm"
          style={{ left: `${percent}%` }}
        />
        {floating !== null ? (
          <div
            aria-hidden
            className="pointer-events-none absolute bottom-full mb-2 -translate-x-1/2 rounded-sm bg-popover px-1.5 py-0.5 text-xs text-popover-foreground shadow-sm ring-1 ring-border font-[family-name:var(--mini-font-data)] tabular-nums"
            style={{ left: `${max > 0 ? clamp(floating / max, 0, 1) * 100 : 0}%` }}
          >
            {formatClock(floating, true)}
          </div>
        ) : null}
      </div>
    </div>
  )
}

import { MinusIcon, PlusIcon } from "lucide-react"

import { Button } from "@/components/ui/button"

import { formatSpeed, SPEEDS } from "./playback"

/** "- 1x +" control that steps through the playback speeds. */
export function SpeedStepper({
  speed,
  onStep,
}: {
  speed: number
  onStep: (direction: 1 | -1) => void
}) {
  return (
    <div role="group" aria-label="Playback speed" className="flex items-center gap-0.5">
      <Button
        variant="ghost"
        size="icon-xs"
        aria-label="Slower"
        disabled={speed <= SPEEDS[0]}
        onClick={() => onStep(-1)}
      >
        <MinusIcon aria-hidden />
      </Button>
      <span
        aria-live="polite"
        className="w-8 text-center text-xs tabular-nums font-[family-name:var(--mini-font-data)]"
      >
        {formatSpeed(speed)}
      </span>
      <Button
        variant="ghost"
        size="icon-xs"
        aria-label="Faster"
        disabled={speed >= SPEEDS[SPEEDS.length - 1]}
        onClick={() => onStep(1)}
      >
        <PlusIcon aria-hidden />
      </Button>
    </div>
  )
}

import { useEffect, useMemo, useRef, useState } from "react"
import {
  ArrowLeftRightIcon,
  CircleIcon,
  FlameIcon,
  MapPinIcon,
  MousePointerClickIcon,
  PlayIcon,
  TerminalIcon,
  type LucideIcon,
} from "lucide-react"

import { EmptyState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"

import { activeIndex, filterEntries, formatClock } from "./playback"
import type { ReplayEvent } from "./types"

const ICONS: Record<string, LucideIcon> = {
  click: MousePointerClickIcon,
  navigation: MapPinIcon,
  error: FlameIcon,
  console: TerminalIcon,
  network: ArrowLeftRightIcon,
}

// the scroll container is the rows' offset parent, so offsetTop is already relative to it
function rowInView(container: HTMLElement, row: HTMLElement) {
  const top = row.offsetTop
  return (
    top >= container.scrollTop &&
    top + row.offsetHeight <= container.scrollTop + container.clientHeight
  )
}

/** Entries in time order that follow the playhead and seek when an entry's time is clicked. */
export function TimedList({
  entries,
  time,
  onSeek,
  label,
  emptyTitle = "Nothing to show",
  emptyDescription,
}: {
  entries: ReplayEvent[]
  time: number
  onSeek: (ms: number) => void
  label: string
  emptyTitle?: string
  emptyDescription?: string
}) {
  const [query, setQuery] = useState("")
  const [away, setAway] = useState(false)
  const containerRef = useRef<HTMLDivElement>(null)
  const rowRefs = useRef(new Map<string, HTMLLIElement>())
  const ownScroll = useRef(false)

  const shown = useMemo(() => filterEntries(entries, query), [entries, query])
  const current = activeIndex(shown, time)
  const currentId = current === -1 ? null : shown[current].id

  const scrollToCurrent = () => {
    const container = containerRef.current
    const row = currentId ? rowRefs.current.get(currentId) : undefined
    if (!container || !row || rowInView(container, row)) return
    const top = row.offsetTop
    const target =
      top < container.scrollTop
        ? top
        : top + row.offsetHeight - container.clientHeight
    if (target === container.scrollTop) return
    ownScroll.current = true
    container.scrollTop = Math.max(0, target)
  }

  useEffect(() => {
    if (!away) scrollToCurrent()
    // follows the playhead only when the current entry or the list changes
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentId, shown, away])

  const onScroll = () => {
    if (ownScroll.current) {
      ownScroll.current = false
      return
    }
    const container = containerRef.current
    const row = currentId ? rowRefs.current.get(currentId) : undefined
    if (!container || !row) return
    setAway(!rowInView(container, row))
  }

  const seek = (at: number) => {
    setAway(false)
    onSeek(at)
  }

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="shrink-0 px-2 pb-2">
        <Input
          type="search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder={`Filter ${label.toLowerCase()}`}
          aria-label={`Filter ${label.toLowerCase()}`}
          className="h-7 text-xs"
        />
      </div>
      <div className="relative min-h-0 flex-1">
        {shown.length === 0 ? (
          query.trim() ? (
            <EmptyState
              title={`No entries match "${query.trim()}"`}
              action={
                <Button variant="outline" size="sm" onClick={() => setQuery("")}>
                  Clear filter
                </Button>
              }
            />
          ) : (
            <EmptyState title={emptyTitle} description={emptyDescription} />
          )
        ) : (
          <div
            ref={containerRef}
            onScroll={onScroll}
            className="relative h-full overflow-y-auto"
          >
            <ul aria-label={label} className="flex flex-col">
              {shown.map((entry, index) => {
                const Icon = ICONS[entry.kind] ?? CircleIcon
                const isCurrent = index === current
                const future = index > current
                const rule = future && index === current + 1
                return (
                  <li
                    key={entry.id}
                    ref={(node) => {
                      if (node) rowRefs.current.set(entry.id, node)
                      else rowRefs.current.delete(entry.id)
                    }}
                    aria-current={isCurrent ? "true" : undefined}
                    className={cn(
                      "flex items-start gap-2 border-t px-2 py-1.5",
                      rule ? "border-t-primary" : "border-t-border",
                      isCurrent && "bg-[var(--mini-accent-soft)]",
                      future && "text-muted-foreground"
                    )}
                  >
                    <span
                      className={cn(
                        "mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-full bg-muted",
                        entry.tone === "error" || entry.kind === "error"
                          ? "text-destructive"
                          : "text-foreground"
                      )}
                    >
                      <Icon className="size-3" aria-hidden />
                    </span>
                    <div className="min-w-0 flex-1">
                      <p
                        className={cn(
                          "truncate text-sm font-medium",
                          (entry.tone === "error" || entry.kind === "error") &&
                            "text-destructive"
                        )}
                      >
                        {entry.label}
                      </p>
                      {entry.detail ? (
                        <p
                          title={entry.detail}
                          className="truncate text-xs text-muted-foreground font-[family-name:var(--mini-font-data)]"
                        >
                          {entry.detail}
                        </p>
                      ) : null}
                    </div>
                    <Button
                      variant="ghost"
                      size="xs"
                      aria-label={`Seek to ${formatClock(entry.at)}, ${entry.label}`}
                      onClick={() => seek(entry.at)}
                      className="shrink-0 tabular-nums"
                    >
                      <PlayIcon aria-hidden />
                      {formatClock(entry.at)}
                    </Button>
                  </li>
                )
              })}
            </ul>
          </div>
        )}
        {away && shown.length > 0 ? (
          <Button
            size="xs"
            variant="secondary"
            onClick={() => {
              setAway(false)
              scrollToCurrent()
            }}
            className="absolute bottom-2 left-1/2 -translate-x-1/2 shadow-sm ring-1 ring-border"
          >
            Jump to current time
          </Button>
        ) : null}
      </div>
    </div>
  )
}

export type ReplayEvent = {
  id: string
  /** Milliseconds from the start of the replay. */
  at: number
  /** "click", "navigation" and "error" get marks on the lane; any string may feed a tab. */
  kind: string
  label: string
  detail?: string
  tone?: "error"
  /** Click position as percent of the frame; moves the cursor. */
  point?: { x: number; y: number }
}

export type ReplaySnapshot<S = unknown> = {
  id: string
  at: number
  url: string
  state: S
}

export type ReplayRecording<S = unknown> = {
  id: string
  user: string
  meta?: string
  whenLabel?: string
  durationMs: number
  snapshots: ReplaySnapshot<S>[]
  events: ReplayEvent[]
}

